import {keys,totals,localDate} from './core.mjs';
export const escapeHtml=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export const storageKey=uid=>{if(!uid)throw Error('A user is required');return 'gamna:diary:'+uid;};
export function csvCell(value){let s=String(value??'');if(/^[\s]*[=+@-]/.test(s))s="'"+s;return '"'+s.replaceAll('"','""')+'"';}
export function diaryCsv(state){const rows=[['Date','Type','Name','Meal','Grams','Calories (kcal)','Protein (g)','Fat (g)','Carbs (g)','Fiber (g)','Weight (kg)','Sleep (h)','Activity (min)']];for(const [date,d] of Object.entries(state.days).sort()){
rows.push([date,'Check-in','','','','','','','','',d.weight??'',d.sleep??'','']);
for(const m of d.meals)rows.push([date,'Food',m.name,m.meal,m.grams,...keys.map(k=>m.nutrients[k]??''),'','','']);
for(const e of d.exercise)rows.push([date,'Activity',e.name,'','','','','','','','','',e.minutes]);
}return '\ufeff'+rows.map(row=>row.map(csvCell).join(',')).join('\r\n');}
export function periodRows(days,date,length){const end=new Date(date+'T12:00:00');return Array.from({length},(_,i)=>{const dt=new Date(end);dt.setDate(dt.getDate()-length+1+i);const key=localDate(dt),d=days[key];return {date:key,weight:d?.weight??null,sleep:d?.sleep??null,minutes:d?.exercise?.length?d.exercise.reduce((s,e)=>s+e.minutes,0):null,...Object.fromEntries(keys.map(k=>[k,d?.meals?.length&&!totals(d.meals).missing.includes(k)?totals(d.meals)[k]:null]))};});}
export const poses=['Victory lap','Tiny flex','Stretch break','Disco warm-up','Balance mode','Power pose','Happy jog','Big reach','Side stretch','Champion wave','Squat squad','Rest-day dance'];
const limbs=[[-60,-65,60,-65,-26,100,30,100],[-65,0,65,0,-25,100,25,100],[-30,-90,30,-90,-22,100,22,100],[-65,-65,65,35,-40,90,45,65],[-65,10,65,10,-15,100,55,45],[-52,35,52,35,-32,100,32,100],[-45,-35,45,40,-50,65,30,100],[-15,-100,15,-100,-20,100,20,100],[-50,-85,50,35,-30,100,30,100],[-60,35,60,-85,-20,100,20,100],[-60,10,60,10,-60,65,60,65],[-65,-40,65,40,-40,100,50,75]];
export function avatar(pose=0,photo=null,tone='#c79068',hair='#27272b'){
const id='av'+Math.random().toString(36).slice(2),v=limbs[pose%12];const safePhoto=typeof photo==='string'&&/^data:image\/jpeg;base64,[A-Za-z0-9+/=]+$/.test(photo)?photo:null;
return `<svg class="gamna-avatar" viewBox="0 0 240 320" role="img" aria-label="Your companion: ${poses[pose%12]}"><defs><radialGradient id="${id}body"><stop stop-color="#d8ff90"/><stop offset="1" stop-color="#73aa43"/></radialGradient><radialGradient id="${id}skin"><stop stop-color="${/^#[a-f0-9]{6}$/i.test(tone)?tone:'#c79068'}"/><stop offset="1" stop-color="#926c54"/></radialGradient><filter id="${id}shadow"><feDropShadow dx="0" dy="9" stdDeviation="5" flood-opacity=".18"/></filter><clipPath id="${id}crop"><ellipse cx="120" cy="85" rx="39" ry="44"/></clipPath><filter id="${id}toon"><feGaussianBlur stdDeviation=".6"/><feComponentTransfer><feFuncR type="discrete" tableValues="0 .22 .45 .65 .82 1"/><feFuncG type="discrete" tableValues="0 .22 .45 .65 .82 1"/><feFuncB type="discrete" tableValues="0 .22 .45 .65 .82 1"/></feComponentTransfer></filter></defs><ellipse cx="120" cy="285" rx="70" ry="15" fill="#183127" opacity=".14"/><g filter="url(#${id}shadow)"><g stroke="url(#${id}skin)" stroke-width="23" stroke-linecap="round"><path d="M98 150 Q70 150 ${120+v[0]} ${160+v[1]}"/><path d="M142 150 Q172 150 ${120+v[2]} ${160+v[3]}"/></g><g stroke="#243c43" stroke-width="26" stroke-linecap="round"><path d="M106 205 L${120+v[4]} ${170+v[5]}"/><path d="M134 205 L${120+v[6]} ${170+v[7]}"/></g><rect x="86" y="129" width="68" height="87" rx="29" fill="url(#${id}body)"/><text x="120" y="178" text-anchor="middle" fill="#253b28" font-size="30" font-weight="900">g.</text><rect x="109" y="114" width="22" height="25" rx="10" fill="url(#${id}skin)"/><ellipse cx="120" cy="85" rx="42" ry="48" fill="url(#${id}skin)"/>${safePhoto?`<image href="${safePhoto}" x="76" y="37" width="88" height="96" preserveAspectRatio="xMidYMid slice" clip-path="url(#${id}crop)" filter="url(#${id}toon)"/>`:`<path d="M78 76 Q69 20 117 31 Q168 23 163 74 Q143 63 135 48 Q110 75 78 76" fill="${/^#[a-f0-9]{6}$/i.test(hair)?hair:'#27272b'}"/><ellipse cx="104" cy="85" rx="4" ry="6" fill="#222"/><ellipse cx="136" cy="85" rx="4" ry="6" fill="#222"/><path d="M107 103 Q120 116 135 102" fill="white" stroke="#68483e" stroke-width="2"/>`}</g></svg>`;
}
export function safeLink(url){try{const u=new URL(url);return u.protocol==='https:'?u.href:'#';}catch{return '#';}}
